const assert = require('node:assert/strict');
const {readFileSync} = require('node:fs');
const {createHash} = require('node:crypto');
const {join} = require('node:path');
const bytes = readFileSync(join(__dirname, '../config/preview.json'));
const config = JSON.parse(bytes);
assert.equal(config.requestTimeoutMs, 30000, 'Preview timeout must be 30 seconds in milliseconds');
assert.equal(config.retryCount, 2);
assert.equal(config.deliveryEnabled, false);
assert.equal(config.endpoint, 'https://example.invalid/digest');
assert.equal(config.theme, 'compact');
console.log('preview-config-ok sha256=' + createHash('sha256').update(bytes).digest('hex'));
